<div class="revoke-overlay" style="display: @(Visible ? "flex" : "none")">
    <div class="revoke-dialog">
        <h3>Revoke Session</h3>
        <p>Are you sure you want to revoke the session on <strong>@SessionDevice</strong>?</p>
        <div class="revoke-actions">
            <button class="btn-revoke" @onclick="() => OnConfirm.InvokeAsync(true)">Revoke</button>
