        </div>
    </div>
</div>

@code {
    [Parameter] public string SessionDevice { get; set; } = "";
    [Parameter] public bool Visible { get; set; }
    [Parameter] public EventCallback<bool> OnConfirm { get; set; }
}

.revoke-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.revoke-dialog {
    background: #fff;
    border-radius: 8px;
    padding: 28px 32px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.revoke-dialog h3 {
    margin: 0 0 12px;
    font-size: 1.15rem;
    color: #1a1a1a;
}

.revoke-dialog p {
    margin: 0 0 20px;
    color: #555;
    line-height: 1.5;
}

.revoke-actions {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
}

.btn-revoke {
    padding: 8px 18px;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-revoke:hover {
    background: #c82333;
}

.btn-cancel {
    padding: 8px 18px;
    background: #e9ecef;
    color: #495057;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-cancel:hover {
    background: #dee2e6;
}

.password-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 20px;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 18px;
    background: #f8f9fa;
    cursor: pointer;
    user-select: none;
    transition: background 0.15s;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-title {
    font-weight: 600;
    font-size: 0.95rem;
    color: #333;
}

.panel-toggle {
    font-size: 0.8rem;
    color: #6c757d;
}

.panel-body {
    padding: 18px;
    border-top: 1px solid #dee2e6;
}

.form-field {
    margin-bottom: 14px;
}

.form-field label {
    display: block;
    margin-bottom: 5px;
    font-size: 0.85rem;
    font-weight: 500;
    color: #495057;
}

.form-field input {
    width: 100%;
    padding: 8px 12px;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.9rem;
    box-sizing: border-box;
    transition: border-color 0.15s;
}

.form-field input:focus {
    outline: none;
    border-color: #4a90d9;
    box-shadow: 0 0 0 2px rgba(74, 144, 217, 0.15);
}

.message {
    padding: 10px 14px;
    border-radius: 6px;
    margin-bottom: 14px;
    font-size: 0.85rem;
}

.error-message {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.success-message {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.btn-primary {
    padding: 9px 20px;
    background: #4a90d9;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-primary:hover:not(:disabled) {
    background: #3a7bc8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

