+                <input type="password" @bind="confirmPassword" placeholder="Confirm new password" />
+            </div>
+
+            @if (!string.IsNullOrEmpty(errorMessage))
+            {
+                <div class="message error-message">@errorMessage</div>
+            }
+
+            @if (!string.IsNullOrEmpty(successMessage))
+            {
+                <div class="message success-message">@successMessage</div>
+            }
+
+            <button class="btn-primary" @onclick="HandleUpdatePassword" disabled="@isSubmitting">
+                @(isSubmitting ? "Updating…" : "Update Password")
+            </button>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }
+
+    private bool isExpanded;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
+    private string? errorMessage;
+    private string? successMessage;
+    private bool isSubmitting;
+
+    private void ToggleExpanded()
+    {
+        isExpanded = !isExpanded;
+    }
+
+    private async Task HandleUpdatePassword()
+    {
+        errorMessage = null;
+        successMessage = null;
+
+        if (string.IsNullOrWhiteSpace(currentPassword))
+        {
+            errorMessage = "Current password is required.";
+            return;
+        }
+
+        if (string.IsNullOrWhiteSpace(newPassword))
+        {
+            errorMessage = "New password is required.";
+            return;
+        }
+
+        if (newPassword != confirmPassword)
+        {
+            errorMessage = "New password and confirmation do not match.";
+            return;
+        }
+
+        if (newPassword.Length < 6)
+        {
+            errorMessage = "New password must be at least 6 characters.";
+            return;
+        }
+
+        isSubmitting = true;
+
+        try
+        {
+            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
+            successMessage = "Password updated successfully.";
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+
+            _ = HideSuccessAfterDelay();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to update password: {ex.Message}";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private async Task HideSuccessAfterDelay()
+    {
+        await Task.Delay(3000);
+        successMessage = null;
+        await InvokeAsync(StateHasChanged);
+    }
+}
+

