@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _revokeDialogVisible;
    private string _revokeDevice = "";
    private string _revokeSessionId = "";

    private void OpenRevokeDialog(ActiveSession session)
    {
        _revokeDevice = session.Device;
        _revokeSessionId = session.Id;
        _revokeDialogVisible = true;
    }

    private async Task HandleRevokeConfirm(bool confirmed)
    {
        _revokeDialogVisible = false;
        if (confirmed)
        {
            await OnRevokeSession.InvokeAsync(_revokeSessionId);
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

