@inject ISettingsService SettingsService

<div class="profile-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <div class="loading">Loading profile…</div>
    }
    else if (_profile is not null)
    {
        <div class="avatar-area">
            <img src="@_avatarUrl" alt="Avatar" class="avatar-preview" />
            <span class="avatar-url">@_avatarUrl</span>
        </div>

        <div class="form-field">
            <label>Display Name</label>
            <input type="text" @bind="_displayName" />
        </div>

        <div class="form-field">
            <label>Email</label>
            <input type="email" @bind="_email" />
        </div>

        <div class="form-field">
            <label>Bio</label>
            <textarea rows="4" @bind="_bio"></textarea>
        </div>

        @if (_showSuccess)
        {
            <div class="success-message">Profile saved successfully!</div>
        }

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveChanges" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    }
</div>

@code {
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _profile = await SettingsService.GetProfileAsync();
        _savedProfile = _profile;
        ApplyProfile(_profile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _profile = updated;
        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.profile-section h2 {
    margin: 0 0 20px;
    font-size: 1.3rem;
    color: #1a1a1a;
    font-weight: 600;
}

.loading {
    color: #6c757d;
