@inject ISettingsService SettingsService

<div class="notifications-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <div class="loading">Loading notification preferences…</div>
    }
    else if (_prefs is not null)
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
                <span class="toggle-desc">Receive notifications via email</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
                <span class="toggle-desc">Receive browser push notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
                <span class="toggle-desc">Get a weekly summary email</span>
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <p class="channels-desc">Uncheck a channel to receive its notifications.</p>
            <div class="channel-list">
                @for (int i = 0; i < _channels.Count; i++)
                {
                    var index = i;
                    <label class="channel-item">
                        <input type="checkbox" checked="@_channelMuted[index]"
                               @onchange="(e) => ToggleChannel(index, (bool)(e.Value ?? false))" />
                        <span>#@_channels[index]</span>
                    </label>
                }
            </div>
        </div>

        @if (_showSuccess)
        {
            <div class="success-message">Preferences saved successfully!</div>
        }

        <button class="btn-primary" @onclick="SavePreferences" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>
    }
</div>

@code {
    private NotificationPrefs? _prefs;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _channels = new();
    private List<bool> _channelMuted = new();

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = new List<string>(_prefs.MutedChannels);
        _channelMuted = _channels.Select(_ => true).ToList();
        _loading = false;
    }

    private void ToggleChannel(int index, bool muted)
    {
        _channelMuted[index] = muted;
    }

    private async Task SavePreferences()
    {
        _saving = true;
        var mutedChannels = new List<string>();
        for (int i = 0; i < _channels.Count; i++)
        {
            if (_channelMuted[i])
                mutedChannels.Add(_channels[i]);
        }

        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

