<div class="appearance-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <div class="loading">Loading appearance settings…</div>
    }
    else
    {
        <div class="form-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange='() => _theme = theme' />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange='() => _fontSize = size' />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <h3>Language</h3>
            <select class="language-select" @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <div class="form-group">
            <h3>Compact Mode</h3>
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span>Enable compact mode for denser layouts</span>
            </label>
        </div>

        <div class="form-group">
            <h3>Live Preview</h3>
            <div class="preview-area" style="@GetPreviewStyle()">
                <p style="@GetPreviewFontStyle()">
                    The quick brown fox jumps over the lazy dog.
                </p>
                <p style="@GetPreviewFontStyle()">
                    Theme: @_theme · Font Size: @_fontSize · Language: @_language
                </p>
                @if (_compactMode)
                {
                    <p style="font-size: 0.75rem; opacity: 0.7;">Compact mode is on — tighter spacing</p>
                }
            </div>
        </div>

        @if (_showSuccess)
        {
            <div class="success-message">Appearance settings saved!</div>
        }

        <button class="btn-primary" @onclick="SaveAppearance" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background:#1e1e2e; color:#e0e0e0;",
            "System" => "background:#f0f4f8; color:#333;",
            _ => "background:#ffffff; color:#1a1a1a;"
        };

        var padding = _compactMode ? "padding:10px 14px;" : "padding:18px 22px;";
        return $"{bg} {padding} border-radius:8px; border:1px solid #ced4da; transition: all 0.2s;";
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size:0.8rem;",
            "Large" => "font-size:1.15rem;",
            _ => "font-size:0.95rem;"
        };
        var margin = _compactMode ? "margin:2px 0;" : "margin:6px 0;";
        return $"{size} {margin}";
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

