+@using sv_893df9f908cf46dda450ed58296a3410.Components.Pages.Settings
+@inject ISettingsService SettingsService
+
+<div class="security-section">
+    <h2>Security Settings</h2>
+
+    @if (_loading)
+    {
+        <div class="loading">Loading security settings…</div>
+    }
+    else if (_settings is not null)
+    {
+        <div class="section-block">
+            <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
+        </div>
+
+        <div class="section-block">
+            <h3>Two-Factor Authentication</h3>
+            <div class="tfa-row">
+                <label class="tfa-toggle">
+                    <input type="checkbox" @bind="_twoFactorEnabled" />
+                    <span>Enable two-factor authentication</span>
+                </label>
+                @if (_twoFactorEnabled)
+                {
+                    <span class="badge badge-enabled">Enabled</span>
+                }
+                else
+                {
+                    <span class="badge badge-disabled">Disabled</span>
+                }
+            </div>
+        </div>
+
+        <div class="section-block">
+            <h3>Last Password Change</h3>
+            <p class="meta-text">
+                @if (_settings.LastPasswordChange.HasValue)
+                {
+                    @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy 'at' HH:mm UTC")
+                }
+                else
+                {
+                    <span>Never changed</span>
+                }
+            </p>
+        </div>
+
+        <div class="section-block">
+            <h3>Active Sessions</h3>
+            <ActiveSessionsTable Sessions="_settings.Sessions.ToList()"
+                                 CurrentSessionId="@(_settings.Sessions.Count > 0 ? _settings.Sessions[0].Id : "")"
+                                 OnRevokeSession="HandleRevokeSession" />
+        </div>
+    }
+</div>
+
+@code {
+    private SecuritySettings? _settings;
+    private bool _loading = true;
+    private bool _twoFactorEnabled;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadSettings();
+    }
+
+    private async Task LoadSettings()
+    {
+        _loading = true;
+        _settings = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = _settings.TwoFactorEnabled;
+        _loading = false;
+    }
+
+    private async Task HandleChangePassword((string CurrentPassword, string NewPassword) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.CurrentPassword, args.NewPassword);
+        await LoadSettings();
+    }
+
+    private async Task HandleRevokeSession(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        await LoadSettings();
+    }
+}
+

