@page "/settings"
@rendermode InteractiveServer
@using sv_893df9f908cf46dda450ed58296a3410.Components.Pages.Settings

<div class="settings-dashboard">
    <aside class="settings-sidebar-panel">
        <h1 class="settings-title">Settings</h1>
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="HandleSectionChanged" />
    </aside>
    <main class="settings-content">
        @if (_activeSection == "Profile")
        {
            <ProfileSection />
        }
        else if (_activeSection == "Notifications")
        {
            <NotificationsSection />
        }
        else if (_activeSection == "Security")
        {
            <SecuritySection />
        }
        else if (_activeSection == "Appearance")
        {
            <AppearanceSection />
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void HandleSectionChanged(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 60px);
    max-width: 1100px;
    margin: 0 auto;
    gap: 0;
}

.settings-sidebar-panel {
    width: 220px;
    flex-shrink: 0;
    border-right: 1px solid #e9ecef;
    padding: 24px 0 24px 8px;
    background: #fafbfc;
}

.settings-title {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a1a1a;
    margin: 0 0 16px 18px;
}

.settings-content {
    flex: 1;
    padding: 24px 32px;
    min-width: 0;
}

